from pathlib import Path
root=Path(__file__).parent
def write(path,text):
 p=root/path;p.parent.mkdir(parents=True,exist_ok=True);p.write_text(text,encoding='utf-8')
def shell(title,body,prefix=''):
 return f'''<!doctype html><html lang="id"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="description" content="Materi dan eksplorasi interaktif Konsep Dasar IPA untuk mahasiswa PGMI"><title>{title} · Konsep Dasar IPA</title><link rel="stylesheet" href="{prefix}styles.css"></head><body><a class="sr-only" href="#main">Lewati navigasi</a><header class="header"><div class="wrap nav"><a class="brand" href="{prefix}index.html">Inkuiri<span>Lab</span> / IPA</a><nav aria-label="Navigasi utama"><a href="{prefix}index.html#topik">Semua topik</a><a href="{prefix}topik/zat/index.html">Zat</a><a href="{prefix}topik/gaya/index.html">Gaya dan Gerak</a></nav></div></header><main id="main">{body}</main><footer class="footer"><div class="wrap"><span>Konsep Dasar IPA · PGMI · InkuiriLab</span><a href="{prefix}index.html#topik">Kembali ke semua topik ↑</a></div></footer></body></html>'''
art='''<svg viewBox="0 0 420 330" role="img" aria-label="Model gaya pada benda serta partikel padat cair dan gas"><defs><marker id="arr" markerWidth="8" markerHeight="8" refX="6" refY="3" orient="auto"><path d="M0 0L6 3L0 6" fill="#d8eaa3"/></marker></defs><text x="24" y="36" fill="#d8eaa3" font-size="13" letter-spacing="2">AMATI · MODELKAN · JELASKAN</text><path d="M25 194H395" stroke="#83a598"/><rect x="170" y="105" width="85" height="85" rx="15" fill="#d8eaa3"/><text x="188" y="151" font-size="20" fill="#133e35">benda</text><path d="M270 145H360M151 145H70" stroke="#d8eaa3" stroke-width="4" marker-end="url(#arr)"/><text x="310" y="125" fill="white" font-size="13">gaya</text><circle cx="180" cy="195" r="7" fill="#c66a33"/><circle cx="245" cy="195" r="7" fill="#c66a33"/><g fill="#ecf5e0"><circle cx="40" cy="265" r="6"/><circle cx="60" cy="265" r="6"/><circle cx="40" cy="285" r="6"/><circle cx="60" cy="285" r="6"/><circle cx="180" cy="267" r="6"/><circle cx="198" cy="280" r="6"/><circle cx="213" cy="266" r="6"/><circle cx="190" cy="294" r="6"/><circle cx="315" cy="250" r="6"/><circle cx="375" cy="272" r="6"/><circle cx="340" cy="298" r="6"/></g><text x="30" y="320" fill="#c8dece" font-size="11">PADAT</text><text x="175" y="320" fill="#c8dece" font-size="11">CAIR</text><text x="330" y="320" fill="#c8dece" font-size="11">GAS</text></svg>'''
topics=[('Hakikat IPA','Metode ilmiah dan keterampilan proses sains','Fondasi IPA'),('Besaran satuan dan pengukuran','Menghasilkan data dengan angka dan satuan','Fisika'),('Materi zat dan perubahannya','Wujud, model partikel, perubahan fisika dan kimia','Fisika'),('Gaya dan gerak','Interaksi, resultan gaya, dan perubahan gerak','Fisika'),('Usaha energi dan perubahannya','Menelusuri perpindahan dan perubahan energi','Fisika'),('Suhu kalor dan perpindahan panas','Menjelaskan pertukaran energi termal','Fisika'),('Gelombang dan bunyi','Getaran dan perambatan gangguan','Fisika'),('Cahaya dan sifat sifatnya','Pemantulan, pembiasan, dan penglihatan','Fisika'),('Listrik dan magnet','Muatan, rangkaian, dan interaksi magnetik','Fisika'),('Keanekaragaman makhluk hidup','Mengamati ciri dan mengelompokkan organisme','Biologi'),('Struktur dan fungsi tumbuhan','Hubungan bagian tumbuhan dan fungsinya','Biologi'),('Struktur dan fungsi hewan','Mengenali struktur dan adaptasi hewan','Biologi'),('Sistem organ manusia','Kerja organ yang saling berkaitan','Biologi'),('Ekosistem dan interaksi','Hubungan organisme dan lingkungan','Biologi'),('Bumi cuaca dan lingkungan','Perubahan yang terjadi di sekitar kita','Bumi dan Antariksa'),('Tata surya dan benda langit','Bumi sebagai bagian dari sistem yang lebih luas','Bumi dan Antariksa')]
cards=''
for i,(name,desc,group) in enumerate(topics,1):
 url={3:'topik/zat/index.html',4:'topik/gaya/index.html'}.get(i)
 cards+=f'<article class="topic {"available" if url else "unavailable"}"><div class="number">{i:02}</div><span class="tag">{group}</span><h3>{name}</h3><p>{desc}</p>'+ (f'<a class="link" href="{url}">Buka materi →</a>' if url else '<span class="small">Belum tersedia</span>')+'</article>'
write('index.html',shell('Beranda',f'''<section class="hero"><div class="wrap hero-grid"><div><span class="eyebrow">Konsep Dasar IPA / PGMI</span><h1>Memahami alam.<br>Menalar dari bukti.</h1><p class="lead">Jelajahi konsep IPA melalui fenomena, pertanyaan, dan model interaktif. Bangun penjelasan yang dapat Anda pertanggungjawabkan sebagai calon guru MI.</p><div class="buttons"><a class="btn" href="topik/gaya/index.html">Pelajari Gaya dan Gerak →</a><a class="btn light" href="#topik">Jelajahi topik</a></div></div><div class="hero-art">{art}</div></div></section><div class="wrap strip"><span>16 topik dalam peta mata kuliah</span><span>2 topik tersedia</span><span>Materi · Simulasi · Penyelidikan</span></div><section class="section" id="topik"><div class="wrap"><div class="section-head"><div><span class="eyebrow">Peta pembelajaran</span><h2>Pilih topik untuk mulai</h2></div><p class="small">Materi ditambahkan bertahap.</p></div><div class="grid">{cards}</div></div></section><section class="section"><div class="wrap two"><article class="card"><h3>Belajar melalui pertanyaan</h3><p>Awali dengan dugaan. Amati apa yang berubah, bandingkan hasil, lalu perbaiki penjelasan Anda berdasarkan bukti.</p></article><article class="card"><h3>Dari mahasiswa menjadi guru</h3><p>Model membantu menjelaskan konsep yang sulit dilihat. Periksa batas model sebelum menggunakannya untuk menjelaskan IPA kepada siswa SD/MI.</p></article></div></section>'''))
body='''<div class="wrap crumb"><a href="../../index.html">Semua topik</a> / 04 Gaya dan Gerak</div><section class="hero"><div class="wrap hero-grid"><div><span class="eyebrow">Topik 04 / Fisika</span><h1>Mengapa gerak<br>benda berubah?</h1><p class="lead">Apakah benda yang bergerak harus terus didorong? Telusuri hubungan gaya, massa, dan perubahan kecepatan melalui pengamatan dan eksperimen model.</p><div class="buttons"><a class="btn" href="#materi">Mulai dari fenomena ↓</a><a class="btn light" href="#simulasi">Buka simulasi</a></div></div><div class="hero-art">'''+art+'''</div></div></section><div class="wrap strip"><span>Alokasi kegiatan 100 menit</span><span>Fokus: gaya neto mengubah kecepatan</span><span>Peralatan: buku dan permukaan meja</span></div><div class="wrap anchor-nav"><a href="#materi">1 Materi</a><a href="#simulasi">2 Simulasi</a><a href="#kegiatan">3 Penyelidikan</a><a href="#latihan">4 Latihan</a><a href="#refleksi">5 Refleksi</a></div>
<section class="section" id="materi"><div class="wrap content"><div class="step">01 / Cermati fenomena · 25 menit</div><h2>Buku berhenti setelah didorong. Mengapa?</h2><p>Dorong perlahan sebuah buku di atas meja, lalu lepaskan tangan. Buku bergerak sesaat kemudian berhenti. Pengamatan ini sering membawa kita pada dugaan bahwa benda membutuhkan dorongan terus-menerus agar tetap bergerak.</p><p class="question">Apakah buku berhenti karena dorongannya habis, atau karena ada interaksi lain?</p><p>Sesudah tangan dilepas, dorongan tangan tidak lagi bekerja. Namun buku masih berinteraksi dengan permukaan meja. Gaya gesek melawan gerak relatif buku terhadap meja dan memperlambatnya. Karena itu, kejadian tersebut belum menunjukkan bagaimana benda akan bergerak jika gaya gesek dihilangkan.</p><h3>Gerak selalu dibandingkan dengan titik acuan</h3><p>Seseorang yang duduk di bus diam terhadap kursinya, tetapi bergerak terhadap jalan ketika bus melaju. Sebuah benda disebut bergerak bila posisinya berubah terhadap acuan yang dipilih. Kelajuan menyatakan seberapa cepat jarak ditempuh; kecepatan juga memuat arah. Saat arah berubah, kecepatan berubah meskipun kelajuannya tetap.</p><p class="question">Ketika kendaraan berbelok dengan kelajuan tetap, apakah kecepatannya tetap?</p><p>Tidak. Perubahan arah adalah perubahan kecepatan. Percepatan menyatakan perubahan kecepatan per satuan waktu; percepatan dapat mengubah kelajuan, arah, atau keduanya.</p><h3>Gaya adalah interaksi</h3><p>Tarikan dan dorongan merupakan contoh gaya. Gaya bekerja karena interaksi antara dua benda. Tangan mendorong buku melalui kontak; Bumi menarik buku melalui gravitasi. Gaya dapat mengubah kecepatan atau bentuk benda, tetapi adanya gaya tidak selalu membuat benda mulai bergerak.</p><p class="question">Buku yang diam tetap ditarik gravitasi. Mengapa tidak jatuh menembus meja?</p><p>Meja memberikan gaya normal ke atas, sedangkan gravitasi bekerja ke bawah. Untuk buku yang diam pada meja horizontal tanpa gaya vertikal lain, keduanya seimbang. Resultan atau gaya neto adalah jumlah semua gaya pada satu benda dengan memperhatikan arah. Resultan nol dapat terjadi ketika beberapa gaya tetap bekerja.</p><h3>Apa yang berubah jika gaya neto tidak nol?</h3><p>Hukum I Newton menjelaskan bahwa, pada acuan inersial, benda mempertahankan keadaan diam atau gerak lurus dengan kecepatan tetap jika resultan gaya nol. Hukum II Newton menghubungkan resultan gaya dengan percepatan untuk massa tetap:</p><p class="equation">ΣF = m a</p><p>Gaya diukur dalam newton (N), massa dalam kilogram (kg), dan percepatan dalam meter per sekon kuadrat (m/s²). Gaya neto yang sama menghasilkan percepatan lebih kecil pada massa lebih besar. Arah percepatan mengikuti gaya neto, tetapi tidak harus sama dengan arah kecepatan: sebuah benda yang bergerak ke kanan dapat mengalami percepatan ke kiri sehingga melambat.</p><p class="question">Jika gaya neto nol, apakah benda pasti diam?</p><p>Tidak. Kecepatannya tetap; nilainya dapat nol maupun tidak nol. Pada simulasi berikut, uji benda yang sudah bergerak ketika dorongan dan gesekan sama-sama nol.</p><h3>Pasangan aksi dan reaksi bekerja pada benda berbeda</h3><p>Ketika tangan mendorong buku, buku juga memberikan gaya yang sama besar dan berlawanan arah pada tangan. Pasangan Hukum III Newton itu bekerja pada dua benda berbeda, sehingga tidak saling meniadakan dalam perhitungan resultan gaya pada buku. Gaya berat buku dan gaya normal meja juga bukan pasangan aksi–reaksi karena keduanya bekerja pada buku.</p></div></section>
<section class="section" id="simulasi"><div class="wrap"><div class="step">02 / Uji model · 25 menit</div><h2>Gaya nol, gerak masih ada?</h2><p class="lead">Buat prediksi sebelum menjalankan model. Positif berarti ke kanan. Panah menunjukkan gaya horizontal; skala tampilan benda mengikuti kamera.</p><div class="sim"><div class="sim-screen"><svg id="world" viewBox="0 0 640 300" role="img" aria-label="Benda pada permukaan horizontal dengan panah gaya dorong dan gesekan"><defs><marker id="arrowForce" markerWidth="8" markerHeight="8" refX="7" refY="3" orient="auto"><path d="M0 0L7 3L0 6" fill="#14634e"/></marker><marker id="arrowFriction" markerWidth="8" markerHeight="8" refX="7" refY="3" orient="auto"><path d="M0 0L7 3L0 6" fill="#b45526"/></marker></defs><rect width="640" height="300" fill="#e9f1e4"/><text x="24" y="32" fill="#50685b" font-size="14">Model satu dimensi · acuan permukaan meja</text><path d="M0 220H640" stroke="#839a80" stroke-width="3"/><g id="ruler"></g><rect x="280" y="146" width="80" height="72" rx="10" fill="#d7e5a1" stroke="#14634e" stroke-width="2"/><text id="massLabel" x="320" y="186" text-anchor="middle" fill="#153e36" font-size="18">2 kg</text><path id="forceArrow" stroke="#14634e" stroke-width="4" marker-end="url(#arrowForce)"/><text id="forceLabel" fill="#14634e" font-size="15" text-anchor="middle"/><path id="frictionArrow" stroke="#b45526" stroke-width="4" marker-end="url(#arrowFriction)"/><text id="frictionLabel" fill="#b45526" font-size="15" text-anchor="middle"/></svg><div class="readouts"><div>Posisi x<strong id="pos">0.00 m</strong></div><div>Kecepatan v<strong id="velocity">0.00 m/s</strong></div><div>Percepatan a<strong id="accel">0.00 m/s²</strong></div></div><p id="netText">Gaya neto 0 N</p><p class="small">Model ideal, bidang horizontal. Gaya vertikal seimbang. μ dipakai sama untuk batas gesek statis dan gesek kinetis. Keausan dan hambatan udara diabaikan. Lama setiap percobaan maksimum 15 s.</p><p id="timeText" class="small">Waktu 0.00 s</p></div><div class="card controls"><h3>Atur satu faktor dahulu</h3><div class="presets"><button data-preset="inertia">Tanpa gesekan</button><button data-preset="friction">Berhenti oleh gesekan</button><button data-preset="push">Dorong dari diam</button></div><label for="mass">Massa <output id="massOut">2 kg</output></label><input id="mass" type="range" min="1" max="10" step="1" value="2"><label for="force">Gaya dorong <output id="forceOut">0 N</output></label><input id="force" type="range" min="-20" max="20" step="1" value="0"><label for="mu">Koefisien gesek μ <output id="muOut">0.00</output></label><input id="mu" type="range" min="0" max="0.5" step="0.05" value="0"><label for="v0">Kecepatan awal <output id="v0Out">2 m/s</output></label><input id="v0" type="range" min="-4" max="4" step="0.5" value="2"><p class="small">Pengaturan massa, μ, dan kecepatan awal diterapkan setelah reset. Gaya dorong dapat diubah ketika model berjalan.</p><div class="buttons"><button id="run" class="btn">Jalankan</button><button id="reset" class="btn light">Reset</button><button id="release" class="btn light">Lepaskan dorongan</button></div><p class="small" id="simStatus" role="status" style="margin-top:16px">Model siap. Periksa pengaturan sebelum menjalankan.</p></div></div><div class="two" style="margin-top:24px"><article class="card"><h3>Bandingkan dua keadaan</h3><p>Pilih “Tanpa gesekan”, lalu jalankan. Reset, pilih “Berhenti oleh gesekan”, dan jalankan lagi. Apa perbedaannya? Faktor mana yang diubah?</p></article><article class="card"><h3>Uji peran massa</h3><p>Pilih “Dorong dari diam”. Bandingkan massa 2 kg dan 4 kg dengan gaya 8 N dan μ = 0. Reset tiap percobaan. Bandingkan percepatan, bukan hanya posisi akhir.</p></article></div></div></section>
<section class="section" id="kegiatan"><div class="wrap"><div class="step">03 / Hubungkan dengan pengamatan · 20 menit</div><h2>Dari model ke permukaan meja</h2><div class="two"><article class="card"><h3>Lakukan dan catat</h3><p>Gunakan buku yang sama pada dua permukaan datar dengan tekstur berbeda, misalnya meja dan alas kain. Dorong perlahan dengan usaha membuat dorongan awal serupa, lalu amati geraknya setelah tangan dilepas.</p><p class="question">Apakah perbedaan jarak berhenti sudah cukup untuk menentukan besar gaya gesek?</p><p>Belum. Dorongan manual tidak menjamin kecepatan awal yang sama. Percobaan ini mendukung pengamatan kualitatif; pengukuran gaya gesek memerlukan rancangan dan alat yang lebih memadai.</p><p class="small">Lakukan pada meja yang stabil dan hentikan buku sebelum mencapai tepi.</p></article><article class="card"><h3>Contoh gaya di sekitar kita</h3><div class="table-wrap"><table><thead><tr><th>Interaksi</th><th>Gaya dan pengaruhnya</th></tr></thead><tbody><tr><td>Bumi dan benda</td><td>Gravitasi menarik benda ke arah Bumi; berat W = mg berbeda dari massa.</td></tr><tr><td>Dua permukaan</td><td>Gesekan dapat menghambat geser; juga membantu berjalan tanpa selip.</td></tr><tr><td>Pegas dan benda</td><td>Gaya pemulih melawan perubahan panjang. F = −kx berlaku dalam batas elastis model pegas ideal.</td></tr><tr><td>Tangan dan spons</td><td>Gaya dapat mengubah bentuk, meskipun benda tidak berpindah jauh.</td></tr></tbody></table></div></article></div></div></section>
<section class="section" id="latihan"><div class="wrap content"><div class="step">04 / Periksa penjelasan · 15 menit</div><h2>Apakah alasan Anda didukung konsep?</h2><p>Pilih jawaban, kemudian periksa umpan balik. Jawaban dapat diubah untuk mempelajari alasan pada setiap soal.</p><form id="quiz" class="card"></form><div class="buttons"><button id="checkQuiz" class="btn">Periksa jawaban</button><button id="resetQuiz" class="btn light">Ulangi latihan</button></div><p id="quizScore" role="status" style="margin-top:16px"></p></div></section>
<section class="section" id="refleksi"><div class="wrap content"><div class="step">05 / Tinjau pemahaman · 15 menit</div><h2>Perbaiki jawaban awal Anda</h2><p>Kembali pada buku yang berhenti setelah didorong. Gunakan pengamatan, model, dan konsep gaya neto untuk menyusun penjelasan yang lebih tepat.</p><div class="card notes"><label for="prediction">Dugaan awal sebelum mencoba simulasi</label><textarea id="prediction" placeholder="Apakah benda yang bergerak harus selalu didorong? Tuliskan alasan awal Anda."></textarea><label for="evidence">Hasil pengamatan dan perbandingan</label><textarea id="evidence" placeholder="Sebutkan pengaturan model, hasil yang diamati, dan faktor yang Anda bandingkan."></textarea><label for="reflection">Penjelasan akhir dan batas bukti</label><textarea id="reflection" placeholder="Apa yang berubah pada pemahaman Anda? Apa keterbatasan model dan dorongan manual?"></textarea><div class="buttons"><button class="btn" id="download">Unduh catatan</button><button class="btn light" id="clearNotes">Hapus catatan</button></div><p class="small" id="notesStatus" role="status" style="margin-top:12px">Catatan tersimpan otomatis di peramban ini jika penyimpanan lokal tersedia. Catatan dan nilai tidak dikirim ke dosen.</p></div><h3 style="margin-top:28px">Sumber konsep dan bacaan lanjutan</h3><ul class="sources"><li>OpenStax. (2016). <i>University Physics Volume 1</i>, Bab 5–6: hukum Newton dan gaya gesek. <a href="https://openstax.org/books/university-physics-volume-1/pages/5-introduction" target="_blank" rel="noopener">Baca sumber</a>.</li><li>PhET Interactive Simulations, University of Colorado Boulder. <i>Forces and Motion: Basics</i>. <a href="https://phet.colorado.edu/en/simulations/forces-and-motion-basics" target="_blank" rel="noopener">Eksplorasi pembanding</a>.</li></ul></div></section><script type="module" src="../../motion.js"></script>'''
write('topik/gaya/index.html',shell('Gaya dan Gerak',body,'../../'))
write('README.md','''# Konsep Dasar IPA

Portal pembelajaran statis untuk mahasiswa PGMI. Beranda memuat peta 16 topik; Zat dan Perubahannya serta Gaya dan Gerak tersedia. Topik lain ditandai belum tersedia.

## Menjalankan lokal

Gunakan server HTTP, misalnya `python3 -m http.server 8000`, lalu buka `http://localhost:8000`. JavaScript module memerlukan HTTP, bukan membuka file langsung.

## Publikasi GitHub Pages

Di Settings → Pages → Build and deployment, pilih Deploy from a branch, branch `main`, folder `/ (root)`, lalu Save. Situs: https://julesnh21.github.io/konsep-dasar-IPA/ setelah proses deployment selesai.

## Struktur

- `index.html`: menu topik.
- `topik/gaya/index.html`, `motion.js`, `physics.js`: materi, simulasi gaya satu dimensi, latihan, dan refleksi.
- `topik/zat/`: materi sebelumnya yang diintegrasikan. Ilustrasi tetap bersumber dari repositori asal melalui URL mentah GitHub.
- `styles.css`: gaya portal dan topik Gaya dan Gerak.

## Batas model dan data

Model menggunakan bidang horizontal, g = 9.8 m/s², dan koefisien gesek statis serta kinetis yang disamakan. Tidak mencakup gerak rotasi atau hambatan udara. Catatan refleksi tersimpan lokal di peramban dan dapat diunduh; nilai latihan tidak terkirim ke server atau dosen.

Untuk menambah topik: buat folder di `topik/`, gunakan navigasi relatif, dan aktifkan kartu topik di beranda. Berkas `build-site.py` membangun beranda dan halaman Gaya; jika mengedit HTML langsung, selaraskan juga skrip tersebut sebelum menjalankannya lagi.
''')
write('.nojekyll','')
